def _serve_doc(self, name):
    if (
        not name
        or "/" in name
        or "\\" in name
        or ".." in name
        or os.path.isabs(name)
    ):
        self._json(400, {"error": "invalid document name"})
        return
    root = Path(DATA_DIR).resolve()
    candidate = (root / name).resolve()
    try:
        candidate.relative_to(root)
    except ValueError:
        self._json(404, {"error": "not found"})
